mapper.select:
Select * from innovation_projects as ip join On student_information as si on ip.student_number=si.student_number


        AND ip.student_name LIKE CONCAT('%',#{studentName},'%')


        AND ip.student_number LIKE CONCAT('%',#{studentNumber},'%')


        and si.classes = #{classes}


        and si.grade = #{grade}


        and si.major = #{major}


        and si.college = #{college}
